// Глобальное переопределение frappe.msgprint для отлова пустых сообщений
const originalMsgprint = frappe.msgprint;

frappe.msgprint = function(message, opts) {
    console.trace('frappe.msgprint called with:', message, opts);

    // Обработка массива сообщений
    if (Array.isArray(message)) {
        const filteredMessages = message.filter(msg => {
            if (typeof msg === 'string') {
                try {
                    const parsed = JSON.parse(msg);
                    return parsed.message && parsed.message.trim() !== "";
                } catch {
                    return msg.trim() !== "";
                }
            }
            return true; // оставляем нестроковые элементы
        });

        if (filteredMessages.length === 0) {
            console.warn("Все сообщения пустые - игнорируем");
            return;
        }
        
        return originalMsgprint(filteredMessages, opts);
    }

    // Обработка строки
    if (typeof message === 'string' && message.trim() === "") {
        console.warn("Пустая строка - игнорируем");
        return;
    }

    // Обработка объектов
    if (message && typeof message === 'object' && message.message && message.message.trim() === "") {
        console.warn("Пустое сообщение в объекте - игнорируем");
        return;
    }

    // Во всех остальных случаях вызываем оригинальный метод
    return originalMsgprint.apply(this, arguments);
};

frappe.ui.form.on('Application For Leave', {
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === 'Не согласовано') {
            return requireRejectionComment(frm);
        }
        return true;
    },

    refresh: function(frm) {
        showDashboard(frm);
        checkTransitions(frm);
    },
    
    alto_date: function(frm) {
        let doc = frm.doc;
        if (doc.alfrom_date && doc.alto_date && 
            frappe.datetime.get_day_diff(doc.alfrom_date, doc.alto_date) > 0) {
            frappe.show_alert({
                message: __('Дата окончания не может быть раньше даты начала!'),
                indicator: 'orange'
            }, 5);
            frm.set_value("alto_date", doc.alfrom_date);
        }
    }
});

// Основная функция для обработки комментария при отклонении
function requireRejectionComment(frm) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const dialog = frappe.prompt({
                fieldtype: 'Text',
                label: ('Причина Отклонения'),
                fieldname: 'comment',
                reqd: 1,
                description: ('Кратко укажите причину отклонения заявки')
            }, 
            (data) => {
                if (data.comment && data.comment.trim()) {
                    addSystemComment(frm, data.comment).then(() => {
                        resolve(true);
                    });
                } else {
                    frappe.msgprint(('Необходимо указать причину Отклонения'));
                    resolve(false);
                }
            }, 
            ('Требуется комментарий'), 
            __('Подтвердить'));
            
            // Настройки размера диалога
            dialog.$wrapper.css({
                'z-index': 99999,
                'width': '400px',
                'max-width': '90%',
                'position': 'fixed', // Устанавливаем фиксированное позиционирование
                'top': '50%', // Сдвигаем вниз на 50% высоты экрана
                'left': '50%', // Сдвигаем вправо на 50% ширины экрана
                'transform': 'translate(-50%, -50%)' // Центрируем по обеим осям
            });
            dialog.$wrapper.find('.modal-dialog').css({
                'z-index': 100000,
                'width': 'auto',
                'margin': '0' // Убираем отступы, так как мы уже центрируем через transform
            });
        }, 100);
    });
}


// Функция добавления системного комментария
function addSystemComment(frm, comment) {
    return frappe.call({
        method: "frappe.desk.form.utils.add_comment",
        args: {
            reference_doctype: frm.doctype,
            reference_name: frm.docname,
            content: comment,
            comment_by: frappe.session.user,
            comment_email: frappe.session.user
        },
        freeze: true
    });
}

// Остальные функции без изменений
async function checkTransitions(frm) {
    const tasks = await frappe.db.get_list("Workflow Task", {
        filters: {
            wt_docname: frm.docname,
            status: "Working",
            doc: frm.doctype,
            state: frm.doc.workflow_state,
            _assign: ["like", `%${frappe.session.user}%`]
        },
        fields: ["name"]
    });

    if (tasks.length === 0) {
        setTimeout(() => frm.page.clear_actions_menu(), 500);
    }
}

async function showDashboard(frm) {
    frm.dashboard.reset();
    if (frm.doc.workflow_state === "На согласовании") {
        const wfTasks = await frappe.db.get_list('Workflow Task', {
            fields: ['_assign'],
            filters: { 
                status: 'Working',
                state: 'На согласовании',
                doc: frm.doctype,
                wt_docname: frm.docname,
                "_assign": ["not like", `%${frm.doc.lauser}%`]
            }
        });

        if (wfTasks.length) {
            let approvers = Array.from( new Set( wfTasks.map((x) => {
                return  frappe.utils.parse_json( x._assign );
                }).flat() ) );
                
            frappe.db.get_list('User', {
                fields: ['full_name'],
                filters: { 
                    name: ["in", approvers ]
                }
            } ).then( function( users ) {
                approvers = users.map( ( user ) => user.full_name );
                frm.dashboard.add_comment( "Ожидается согласование от: " + frappe.utils.comma_and( approvers ), "blue", permanent = true);
            });
        }
    }
}
